From 76d1bf145a51e763c8e777d8b60c045e2f2a08a0 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Thu, 26 Nov 2026 00:27:12 +0100
Subject: [PATCH] applets/mediacontroller: open the player when clicking the
 album art

The only way to bring the player's window forward was the Open item in
the context menu, which few people find. Now clicking the album art or
the track details in the popup raises the player and closes the popup.

BUG: 440453
---
 applets/mediacontroller/ExpandedRepresentation.qml | 13 +++++++++++++
 1 file changed, 13 insertions(+)

diff --git a/applets/mediacontroller/ExpandedRepresentation.qml b/applets/mediacontroller/ExpandedRepresentation.qml
index 38d591fa14..3f7dfe3e12 100644
--- a/applets/mediacontroller/ExpandedRepresentation.qml
+++ b/applets/mediacontroller/ExpandedRepresentation.qml
@@ -281,6 +281,19 @@ PlasmaExtras.Representation {
                 rightMargin: Kirigami.Units.gridUnit
             }

+            TapHandler {
+                enabled: root.canRaise
+                onTapped: {
+                    root.raise();
+                    root.expanded = false;
+                }
+            }
+
+            HoverHandler {
+                enabled: root.canRaise
+                cursorShape: Qt.PointingHandCursor
+            }
+
             AlbumArtStackView {
                 id: albumArt

